class _S extends State<W> {
  late final AnimationController _ctrl;
  StreamSubscription? _sub;

  @override
  void initState() {
    super.initState();                 // always first
    _ctrl = AnimationController(vsync: this, duration: kThemeAnimationDuration);
    _sub = stream.listen((_) => setState(() {}));
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final theme = Theme.of(context);   // safe here, not in initState
  }

  @override
  void didUpdateWidget(W old) {
    super.didUpdateWidget(old);
    if (old.id != widget.id) reload(); // the parent handed down a new id
  }

  @override
  void dispose() {
    _sub?.cancel();                    // everything created above
    _ctrl.dispose();
    super.dispose();                   // always last
  }
}

